const products = [
  {id:'esg',category:'ESG',cover:'ESG',name:'ESG Management System',subtitle:'Environment. Social. Governance.',price:79,description:'Plan, implement, manage and improve your ESG activities in one connected Notion workspace.',short:['Shared Master Data layer','20+ operational ESG registers','Strategy, KPIs & documentation'],includes:['ESG strategy, scope, material topics and accountability','Environmental modules: aspects, energy, waste, emissions and performance','Social modules: labor, health & safety, inclusion, human rights and community','Governance modules: ethics, controls, compliance and supplier oversight','Shared Master Data for stakeholders, ESG topics, locations, suppliers and roles','20+ ESG registers, connected databases and a management dashboard','Pre-written customizable policies, procedures and a Document Hub','Training and awareness resources, realistic examples and implementation guidance'],audience:'Small and medium businesses, sustainability managers, compliance professionals, operations teams and ESG consultants.',flow:'Strategy → Risks → Objectives → Actions → Performance → Review → Improvement',scope:'A general ESG management framework, not legal or regulatory advice or a guarantee of compliance. No formal framework-specific mapping or certification against GRI, ESRS/CSRD, ISSB/SASB, ISO 14001, ISO 45001 or other reporting frameworks is included.',preview:['ESG objectives','Risks & opportunities','KPIs & performance'],previewRows:[['Energy reduction objective','Operations'],['Supplier ESG review','Procurement'],['Staff awareness action','People team']]},
  {id:'security',category:'Information security',cover:'ISO 27001',name:'ISO 27001:2022 ISMS',subtitle:'Govern. Protect. Improve.',price:99,description:'Bring risks, assets, controls, evidence and security operations together in one structured system.',short:['Statement of Applicability','Connected risks, assets & controls','Manual & implementation roadmap'],includes:['ISMS dashboard for risks, controls, incidents, vulnerabilities and objectives','Statement of Applicability covering all 93 Annex A controls','Connected asset, threat, vulnerability, risk and treatment structures','Registers for incidents, CAPA, audits, suppliers, training and reviews','Customizable policies, procedures, forms and process descriptions','Information Security Manual and practical implementation roadmap','Traceability from risks to treatments, controls, documents and evidence'],audience:'Small and medium businesses, startups, information security teams, compliance professionals and ISO consultants.',flow:'Risk → Treatment → Annex A Control → Document → Evidence',scope:'Supports implementation and management of an ISMS aligned with ISO/IEC 27001:2022. Using the template does not guarantee compliance or certification.',preview:['Risk register','Statement of Applicability','Corrective actions'],previewRows:[['Access review','IT owner'],['Risk treatment review','Risk owner'],['Evidence collection','Control owner']]},
  {id:'quality',category:'Quality management',cover:'ISO 9001',name:'ISO 9001:2015 QMS',subtitle:'Plan. Do. Check. Act.',price:89,description:'Connect your processes, objectives, audits and improvements in a quality management workspace.',short:['Quality manual & procedures','Objectives, audits & CAPA','Connected registers & dashboard'],includes:['QMS Manual structured around ISO 9001:2015','Ready-to-customize policies, procedures and implementation roadmap','Interconnected registers for risks, opportunities, objectives and KPIs','Customer feedback, satisfaction and supplier management','Internal audit planning, records and follow-up','Nonconformities, corrective actions and management reviews','QMS dashboard, practical examples and guidance'],audience:'Small and growing businesses, quality managers, consultants, QMS coordinators and operations teams.',flow:'Process → Risk → Objective → KPI → Audit → CAPA → Improvement',scope:'Supports QMS implementation and management. It does not provide or guarantee ISO 9001 certification.',preview:['Quality objectives','Internal audits','CAPA register'],previewRows:[['Customer feedback review','Quality manager'],['Process audit','Internal auditor'],['Corrective action follow-up','Process owner']]}
];
const cart = new Set();
const $ = selector => document.querySelector(selector);
const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
function cover(p){return `<div class="product-cover ${p.id}"><div class="cover-top"><span>AVENTO MS</span><span>NOTION TEMPLATE</span></div><div><strong>${p.cover}</strong><div class="cover-sub">${p.subtitle}</div></div><div class="cover-bottom">CONNECTED MANAGEMENT WORKSPACE</div></div>`;}
function renderProducts(filter='all'){
  $('#products').innerHTML=products.filter(p=>filter==='all'||p.id===filter).map(p=>`<article class="product-card">${cover(p)}<div class="product-info"><span class="category">${p.category}</span><h3>${p.name}</h3><p>${p.description}</p><ul>${p.short.map(x=>`<li>${x}</li>`).join('')}</ul><div class="price-row"><strong>${money(p.price)}</strong><span>Illustrative price · USD</span></div><div class="card-actions"><button class="button secondary" data-detail="${p.id}" aria-label="View details for ${p.name}">View details</button><button class="button primary" data-add="${p.id}" aria-label="Add ${p.name} to cart">${cart.has(p.id)?'In cart':'Add to cart'}</button></div></div></article>`).join('');
}
function currentFilter(){return $('.filters .active').dataset.filter;}
function addToCart(id){const p=products.find(p=>p.id===id);if(!p)throw new Error('Unknown product.');if(cart.has(id)){toast('This template is already in your cart.');return {id,added:false};}cart.add(id);updateCart();renderProducts(currentFilter());toast(`${p.name} added to cart.`);return {id,added:true,count:cart.size};}
function updateCart(){
  $('#cart-count').textContent=cart.size;
  const selected=products.filter(p=>cart.has(p.id));
  $('#cart-items').innerHTML=selected.length?selected.map(p=>`<div class="cart-item"><div><h3>${p.name}</h3><p>Digital Notion template · Demo selection</p></div><strong>${money(p.price)}</strong><button class="remove" data-remove="${p.id}" aria-label="Remove ${p.name}">Remove</button></div>`).join(''):'<p>Your cart is empty. Explore the collection to choose a template.</p>';
  $('#cart-summary').innerHTML=selected.length?`<div class="total"><span>Demo total</span><strong>${money(selected.reduce((s,p)=>s+p.price,0))}</strong></div><button class="button primary full" id="begin-checkout">Continue to demo checkout</button><p style="font-size:.875rem">No payment will be taken. Prices are illustrative.</p>`:'<button class="button primary full" data-close="cart-dialog">Continue browsing</button>';
}
function showProduct(id){const p=products.find(p=>p.id===id);if(!p)throw new Error('Unknown product.');$('#product-detail').innerHTML=`<p class="eyebrow">${p.category.toUpperCase()} / NOTION TEMPLATE</p><h2 id="product-title">${p.name}</h2><p>${p.description}</p><div class="price-row"><strong>${money(p.price)}</strong><span>Illustrative price · USD</span></div><button class="button primary" data-add="${p.id}">Add to cart</button><h3>What’s inside</h3><ul class="detail-list">${p.includes.map(x=>`<li>${x}</li>`).join('')}</ul><h3>Everything connects</h3><p>${p.flow}</p><div class="detail-preview"><h3>Workspace preview</h3><p>${p.preview.join(' · ')}</p><table><caption>Illustrative layout and fictional records, not a screenshot of the template.</caption><thead><tr><th>Example activity</th><th>Owner</th></tr></thead><tbody>${p.previewRows.map(row=>`<tr><td>${row[0]}</td><td>${row[1]}</td></tr>`).join('')}</tbody></table></div><h3>Who it’s for</h3><p>${p.audience}</p><h3>Scope</h3><p>${p.scope}</p>`;$('#product-dialog').showModal();}
function checkout(){if(!cart.size)return;$('#cart-dialog').close();const selected=products.filter(p=>cart.has(p.id));$('#checkout-content').innerHTML=`<p class="eyebrow">DEMO CHECKOUT / REVIEW YOUR ORDER</p><h2 id="checkout-title">Ready to get organized?</h2><p class="checkout-notice">This is a simulation. No payment information is requested, no money is charged, and no actual template is delivered.</p><div class="checkout-summary">${selected.map(p=>`<div><span>${p.name}</span><strong>${money(p.price)}</strong></div>`).join('')}<div><strong>Demo total</strong><strong>${money(selected.reduce((s,p)=>s+p.price,0))}</strong></div></div><button class="button primary full" id="complete-demo">Complete demo order</button><p style="font-size:.875rem">Next: try the sample download experience.</p>`;$('#checkout-dialog').showModal();}
function completeDemo(){const selected=products.filter(p=>cart.has(p.id));if(!selected.length)return;const orderId=`DEMO-${Date.now().toString().slice(-6)}`;const guide=`AVENTO MS — PRACTICE STORE\nOrder: ${orderId}\n\nThis is a sample guide, not a purchased Notion template.\nNo money was charged. No actual duplication link is included.\n\nSelected products:\n${selected.map(p=>'- '+p.name).join('\n')}\n\nExample onboarding:\n1. Open the real product duplication link supplied after a real purchase.\n2. Duplicate the workspace into your own Notion account.\n3. Review the implementation roadmap.\n4. Adapt scope, roles, documents, registers and example records.\n\nReal sales, licensed delivery, support and checkout remain to be configured.\n`;$('#checkout-content').innerHTML=`<div class="success-mark" aria-hidden="true">✓</div><p class="eyebrow">SIMULATION COMPLETE</p><h2 id="checkout-title">Your demo order is ready.</h2><p class="demo-id">${orderId}</p><p>No payment was taken. Try downloading a sample setup guide to experience the delivery step.</p><button class="button primary full" id="download-guide">Download sample guide</button><p style="font-size:.875rem">This guide contains no actual template or private Notion link.</p><button class="button secondary full" data-close="checkout-dialog">Back to the collection</button>`;$('#download-guide').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([guide],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='avento-ms-demo-guide.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});cart.clear();updateCart();renderProducts(currentFilter());}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.add)addToCart(b.dataset.add);if(b.dataset.detail)showProduct(b.dataset.detail);if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.remove){cart.delete(b.dataset.remove);updateCart();renderProducts(currentFilter());const target=$('#cart-dialog .remove')||$('#cart-dialog .button');target?.focus();}if(b.dataset.filter){document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderProducts(b.dataset.filter);}if(b.id==='begin-checkout')checkout();if(b.id==='complete-demo')completeDemo();});
$('#open-cart').addEventListener('click',()=>{updateCart();$('#cart-dialog').showModal();});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',event=>{if(event.target===d){const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();}}));
renderProducts();updateCart();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_template_to_cart',description:'Add an Avento MS template to the practice-store cart. Does not place an order or charge money.',inputSchema:{type:'object',properties:{productId:{type:'string',enum:products.map(p=>p.id)}},required:['productId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>addToCart(input.productId)})).catch(()=>{});}catch{}}
